import type { GuidanceDocument } from '../types/guidance';
import type { WorkerSelection } from '../types/change-request-types';
import type { SessionStore } from './SessionStore';
import type {
  StartVariantsBriefContent,
  StaticPreviewTargetElement,
  VariantWorkItemContext,
} from './contracts';
import { AgentVariantsError } from './errors';
import { extendVariantContextBundle } from './variantContext';
import type { VariantsTelemetry } from './variantsTelemetry';

type PendingRefinement = NonNullable<
  ReturnType<SessionStore['getPendingRefinement']>
>;

export type DroppedRefinement = { variantId: string; reason: string };

export type StaticPreviewRefinementRequest = {
  beforeDispatch?: (workItemIds: string[]) => void;
  sessionId: string;
  targets: Array<{
    variantId: string;
    guidance?: GuidanceDocument[];
    instruction: string;
    count?: number;
    briefs?: StartVariantsBriefContent[];
    runLabel?: string;
    fidelity?: import('./contracts').WorkerFidelity;
    workerSelection?: WorkerSelection;
    element?: StaticPreviewTargetElement;
    relevantFiles?: string[];
    requestId?: string;
    profileReferenceMode?: 'inherit' | 'replace';
    additionalContext?: Pick<
      VariantWorkItemContext,
      'contextBundlePath' | 'userContext' | 'rivetMetadata'
    >;
  }>;
};

export interface StaticPreviewRefinementResult {
  droppedRefinements: DroppedRefinement[];
  createdWorkItemIds: string[];
}

interface StaticPreviewRefinementServices {
  request: StaticPreviewRefinementRequest;
  store: SessionStore;
  telemetry: VariantsTelemetry;
  getStaticPreviewHtml: (
    sessionId: string,
    workItemId: string,
  ) => string | undefined;
  emitChange: () => void;
}

export const createStaticPreviewRefinements = ({
  request: args,
  store,
  telemetry,
  getStaticPreviewHtml,
  emitChange,
}: StaticPreviewRefinementServices): StaticPreviewRefinementResult => {
  const seenVariantIds = new Set<string>();
  const droppedRefinements: DroppedRefinement[] = [];
  const createdWorkItemIds: string[] = [];
  const acceptedWorkItemIds: string[] = [];
  const coalesced: Array<{
    item: PendingRefinement;
    input: PendingRefinement['input'];
  }> = [];
  for (const target of args.targets) {
    if (seenVariantIds.has(target.variantId)) continue;
    seenVariantIds.add(target.variantId);
    const mode = target.count == null ? 'comment_refine' : 'vary';
    telemetry.trackAgentVariantsRefinementRequested?.({
      sessionId: args.sessionId,
      requestId: target.requestId,
      entryPoint: 'watch_loop',
      mode,
      projectContextKind: store.getProjectContext(args.sessionId).kind,
      targetVariantId: target.variantId,
      sourceVariantId: mode === 'vary' ? target.variantId : undefined,
      requestedCount: target.count,
      commentCount: 1,
      instructionLength: target.instruction.length,
    });
    const currentHtml = getStaticPreviewHtml(args.sessionId, target.variantId);
    if (target.count == null) {
      try {
        const refineItem = store.createRefineVariantWorkItem({
          sessionId: args.sessionId,
          variantId: target.variantId,
          instruction: target.instruction,
          guidance: target.guidance ?? [],
          currentHtml,
          targetElement: target.element,
          relevantFiles: target.relevantFiles,
          requestId: target.requestId,
          ...(target.fidelity ? { fidelity: target.fidelity } : {}),
          workerSelection: target.workerSelection,
        });
        createdWorkItemIds.push(refineItem.id);
        acceptedWorkItemIds.push(refineItem.id);
      } catch (error) {
        if (
          error instanceof AgentVariantsError &&
          error.code === 'PENDING_CHANGE_CONFLICT'
        ) {
          const pending = store.getPendingRefinement(
            args.sessionId,
            target.variantId,
          );
          const previousInput = pending
            ? structuredClone(pending.input)
            : undefined;
          const folded = store.appendPendingRefineVariantInstruction({
            requestId: target.requestId,
            sessionId: args.sessionId,
            variantId: target.variantId,
            instruction: target.instruction,
            guidance: target.guidance ?? [],
            fidelity: target.fidelity,
            workerSelection: target.workerSelection,
          });
          if (folded && pending && previousInput) {
            coalesced.push({ item: pending, input: previousInput });
            acceptedWorkItemIds.push(pending.id);
          }
          if (!folded) {
            droppedRefinements.push({
              variantId: target.variantId,
              reason: error.message,
            });
          }
        } else if (
          error instanceof AgentVariantsError &&
          error.code === 'VARIANT_NOT_EDITABLE'
        ) {
          droppedRefinements.push({
            variantId: target.variantId,
            reason: error.message,
          });
        } else {
          throw error;
        }
      }
      continue;
    }
    try {
      const source = store.getVariantWorkItemInput(
        args.sessionId,
        target.variantId,
      );
      const additionalContext = target.additionalContext
        ? extendVariantContextBundle({
            sessionId: args.sessionId,
            source: source?.context,
            sourceReferenceMetadata: source?.references,
            profileReferenceMode: target.profileReferenceMode,
            additional: target.additionalContext,
          })
        : undefined;
      const forks = store.createForkedStaticPreviewWorkItems({
        sessionId: args.sessionId,
        sourceVariantId: target.variantId,
        instruction: target.instruction,
        guidance: target.guidance ?? [],
        count: target.count,
        ...(target.briefs ? { briefs: target.briefs } : {}),
        ...(target.runLabel ? { runLabel: target.runLabel } : {}),
        ...(target.fidelity ? { fidelity: target.fidelity } : {}),
        workerSelection: target.workerSelection,
        currentHtml,
        targetElement: target.element,
        relevantFiles: target.relevantFiles,
        requestId: target.requestId,
        context: additionalContext,
      });
      createdWorkItemIds.push(...forks.map((item) => item.id));
      acceptedWorkItemIds.push(...forks.map((item) => item.id));
    } catch (error) {
      if (
        error instanceof AgentVariantsError &&
        (error.code === 'PENDING_CHANGE_CONFLICT' ||
          error.code === 'VARIANT_NOT_EDITABLE' ||
          error.code === 'SOURCE_CONTEXT_INVALID')
      ) {
        droppedRefinements.push({
          variantId: target.variantId,
          reason: error.message,
        });
        continue;
      }
      throw error;
    }
  }
  for (const dropped of droppedRefinements) {
    telemetry.trackAgentVariantsRefinementFailed?.({
      sessionId: args.sessionId,
      targetVariantId: dropped.variantId,
      mode:
        args.targets.find((target) => target.variantId === dropped.variantId)
          ?.count == null
          ? 'comment_refine'
          : 'vary',
      failureReason: dropped.reason,
    });
  }
  try {
    if (acceptedWorkItemIds.length > 0)
      args.beforeDispatch?.(acceptedWorkItemIds);
  } catch (error) {
    for (const entry of coalesced) entry.item.input = entry.input;
    for (const workItemId of createdWorkItemIds) {
      store.cancelWorkItem({
        sessionId: args.sessionId,
        workItemId,
        reason: 'Saved context could not be retained for this request.',
      });
    }
    emitChange();
    throw error;
  }
  emitChange();
  return { droppedRefinements, createdWorkItemIds };
};
